// Counts overlapping occurrences.
//
// @param x {string}  Input string.
// @param y {string}  The substring.
//
// @return {int} Number of occurrences.
how_many_times:{[x;y]
    $[y~""; 0;  // Handle empty substring explicitly to avoid infinite loops/edge cases
        count where 1 = "in" each y#\:x];
