is_prime:{[x]
    / Numbers less than 2 are not prime
    if[x<2; return 0b];

    / 2 and 3 are prime
    if[x in 2 3; return 1b];

    / Even numbers and multiples of 3 are not prime
    if[(x mod 2)=0 | (x mod 3)=0; return 0b];

    / Check for factors up to sqrt(x) using 6k ± 1 optimization
    i:5;
    while[i*i<=x;
        if[(x mod i)=0 | (x mod i+2)=0; return 0b];
        i:+:i+6
    ];

    1b
}
