// The encoder performs a left cyclic shift on groups of 3.
// This function performs a right cyclic shift on groups of 3 to restore the original.
//
// @param x {string} Encoded String.
// @return {string} Decoded String.
decode_cyclic:{[x]
    // Calculate the number of groups: ceil(length / 3)
    // In q: (n + 2) % 3 is the integer ceiling of n/3
    ngrps: (count x + 2) % 3;

    // Split the string into groups of 3 characters
    // i#x creates a table of indices; we use take to extract chunks
    groups: ngrps#x;

    // Apply the reverse rotation to each group
    // If the group has exactly 3 characters, rotate right by 1 (move last to front)
