//
// @param x {int} index in sequence.
// @return {int} the fib4 number.
fib4:{[x]
    $[
        x < 0; 0;                     // invalid index
        x = 0; 0;                     // base case
        x = 1; 0;                     // base case
        x = 2; 2;                     // base case
        x = 3; 0;                     // base case
        / iterative approach for n >= 4
        4 {
            : (x4; x3; x2; x1 + x2 + x3 + x4)
        }[0; 2; 0; 0] x - 3
    ]
}
