//  Given a non-empty list of positive integers, return the greatest integer > 0
//  whose frequency in the list is >= its own value.
//  If no such integer exists, return -1.
//
// @param x {int[]} input list of positive integers
//
// @return {int} the result integer, or -1 if none exists
search:{[x]
    // Count frequencies of each distinct value
    c: count each group x;
    // Keep only values where frequency >= value itself and value > 0
    // (input is guaranteed positive, but we keep the >0 check for clarity)
    valid: where c >= distinct x;
    if[count valid = 0; : -1];
    // Return the maximum of the valid values
    max distinct x where valid
    }
