//        Output: (1, 2)
//
//    Example 2:
//        Input: 12
//        Output: (4, 6)
//
// @param x {int} upper bound on integers
//
// @return {int[]} number of odd/even palindromes
even_odd_palindrome:{[x]
    // Generate integers 1 to x inclusive
    nums: til x+1;

    // Identify palindromes: convert to string, reverse, compare to original
    is_pal: (":$") each nums = {x[til -1 + count x]} each ":$" each nums;

    // Filter to only palindrome numbers
    pals: nums where is_pal;

    // Return tuple: (count of even, count of odd)
    // not mod 2 0#x is equivalent to checking if even
    (sum not 2|pals; sum 2|pals)
    }
