    lens: count each words;

    // Generate a boolean mask: is the length a prime number?
    // (prime[] returns 1b if n is prime, 0b otherwise)
    is_prime: prime each lens;

    // Select words where the length is prime
    prime_words: words where is_prime;

    // Rejoin with spaces; if no words remain, return empty string
    if[count prime_words; : " " sv prime_words];
    : ""
    }
