// @overview 
//  You are given a positive integer n. You have to create an integer array a of length n.
//        For each i (1 ≤ i ≤ n), the value of a[i] = i * i - i + 1.
//        Return the number of triples (a[i], a[j], a[k]) of a where i < j < k, 
//        and a[i] + a[j] + a[k] is a multiple of 3.
//
//    Example :
//        Input: n = 5
//        Output: 1
//        Explanation: 
//        a = [1, 3, 7, 13, 21]
//        The only valid triple is (1, 7, 13).
//
// @param x {int} Positive integer
//
// @return {int} Number of triples
get_max_triples:{[x]
    if[x < 3; :0];

    // Compute residues of a[i] mod 3
    // a[i] = i*i - i + 1
    // r[i] = (i*i - i + 1) mod 3
    r: (1 + (-1 + 1*til x) * til x) mod 3;

    // Count occurrences of residues 0, 1, 2
    c: 0 1 2!count each r;

    // Valid triples must sum to 0 mod 3:
    // 0+0+0, 1+1+1, 2+2+2, 0+1+2
    n0: c[0];
    n1: c[1];
    n2: c[2];

    // nC3 = n*(n-1)*(n-2) / 6
    nC3: {[n] $[n < 3; 0; n * (n - 1) * (n - 2) % 6]]};

    nC3 n0 + nC3 n1 + nC3 n2 + n0 * n1 * n2
    }
```

